from collections import Counter

def min_window(s: str, t: str) -> str:
    if not t:
        return ""

    need = Counter(t)
    window = Counter()
    have = 0
    left = 0
    best_len = len(s) + 1
    best_left = 0

    for right, ch in enumerate(s):
        if ch in need:
            window[ch] += 1
            if window[ch] <= need[ch]:
                have += 1

        while have == len(need):
            cur_len = right - left + 1
            if cur_len < best_len:
                best_len = cur_len
                best_left = left

            left_ch = s[left]
            if left_ch in need:
                if window[left_ch] == need[left_ch]:
                    have -= 1
                window[left_ch] -= 1
            left += 1

    return s[best_left:best_left + best_len] if best_len <= len(s) else ""
```

