def decode_string(s: str) -> str:
    stack = []
    num = 0
    current = ""

    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == "[":
            stack.append((num, current))
            num = 0
            current = ""
        elif ch == "]":
            k, previous = stack.pop()
            current = previous + current * k
        else:
            current += ch

    return current
```

