def count_islands(grid: list[list[str]]) -> int:
    if not grid:
        return 0

    rows = len(grid)
    visited = set()
    count = 0

    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == "1" and (r, c) not in visited:
                count += 1
                stack = [(r, c)]
                visited.add((r, c))

                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if (
                            0 <= nr < rows
                            and 0 <= nc < len(grid[nr])
                            and grid[nr][nc] == "1"
                            and (nr, nc) not in visited
                        ):
                            visited.add((nr, nc))
                            stack.append((nr, nc))

    return count
```

