def word_break(s: str, words: list[str]) -> bool:
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True

    word_set = {w for w in words if w}

    for i in range(1, n + 1):
        for w in word_set:
            lw = len(w)
            if i >= lw and dp[i - lw] and s[i - lw:i] == w:
                dp[i] = True
                break

    return dp[n]
```

